def pq(s):
    return s.replace("\\", "\\\\").replace("'", "\\'").replace("\n", " ")

def demo_program(title, rid, kind, points):
    pts = ",\n    ".join('"%s"' % pq(p) for p in points)
    return ("#!/usr/bin/env python3\n\"\"\"%s -- record demo.\nProperty of Justin Addam Higgins (JAH).\n\"\"\"\n"
            "TITLE = '%s'\nRECORD_ID = '%s'\nKIND = '%s'\n\nCHECKS = [\n    %s,\n]\n\n"
            "def main():\n    print(\"Record demo:\", TITLE)\n    print(\"ID:\", RECORD_ID, \"| kind:\", KIND)\n"
            "    for n, c in enumerate(CHECKS, 1):\n        print(\"  [%%d] %%s\" %% (n, c))\n"
            "    print(\"Checks listed: %%d\" %% len(CHECKS))\n\nif __name__ == \"__main__\":\n    main()\n"
            ) % (pq(title), pq(title), rid, pq(kind), pts)

def build_records(cfg):
    recs = []
    for i, tp in enumerate(cfg["topics"], 1):
        rid = "%s%06d" % (cfg["prefix"], i)
        desc = tp["lead"] + " " + tp["body"]
        p = tp["points"]
        how = ("Reading and using this %s starts with the headline facts \u2014 %s, and %s. "
               "Next, the plan is checked against %s and %s for coordination with the rest of the %s design. %s"
               ) % (cfg["kind"], p[0][0].lower() + p[0][1:], p[1][0].lower() + p[1][1:],
                    p[2][0].lower() + p[2][1:], p[3][0].lower() + p[3][1:],
                    PROJECT[cfg["slug"]], HOW_TAIL[cfg["slug"]])
        rec = {
            "id": rid, "t": tp["title"], "g": tp["group"],
            "name": tp["title"] + " \u2014 " + cfg["kind"],
            "title": tp["title"],
            "description": desc,
            "how_it_works": how,
            "key_points": p + [EXTRA_POINT[cfg["slug"]]],
            "requirements": [tp["req"]] + cfg["reqs"],
            "standards": [tp["std"]] + cfg["stds"],
            "citations": cfg["cites"],
            "src": cfg["src"],
            "ladder_rank": i,
            "ladder_tier": tp["group"],
            "provenance": ("JAH Databases build program \u2014 %s record authored 2026-10-19. Property of Justin Addam Higgins (JAH)."
                           % ("signature-original" if cfg["src"] == "signature" else "public-harvest compiled")),
            "last_verified": "2026-10-19",
            "content_status": "signature-original" if cfg["src"] == "signature" else "established-reference",
            "demo": {"kind": cfg["slug"] + "-demo", "language": "python",
                     "program": demo_program(tp["title"], rid, cfg["kind"], p),
                     "note": "Working demonstration program for this record."},
        }
        recs.append(rec)
    return recs

GEN_TMPL = """(function(){'use strict';
/* JAH %s generator \u2014 jahdb-%s-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function pick(r,s){return r[(s()*r.length)|0];}
var PREFIX=%s;
var FIELDS=%s;
var TOPICS=%s;
function demoProgram(topic,field){
  var safe=String(topic).replace(/\\\\/g,'\\\\\\\\').replace(/"/g,"'");
  return "# JAH %s \\u2014 structural study\\n"
   + "# Field: "+field+"\\n"
   + "record = {'title': \\""+safe+"\\", 'field': \\""+field+"\\"}\\n"
   + "def summarize(r):\\n"
   + "    return r['title'] + ' [' + r['field'] + ']'\\n"
   + "print(summarize(record))\\n"
   + "print('Sample record \\u2014 structural sample, not an archive entry.')\\n";
}
function generate(seed,opts,rnd){
  opts=opts||{}; rnd=rnd||prng(seed);
  var field=opts.field&&FIELDS.indexOf(opts.field)>=0?opts.field:pick(FIELDS,rnd);
  var pool=TOPICS[field]||["General Study"];
  var topic=pick(pool,rnd);
  var id=PREFIX+String(seed).padStart(6,'0');
  return {
    id:id,
    name:topic+' \\u2014 structural study record',
    title:topic,
    description:'SAMPLE RECORD (generated \\u2014 structural sample). A structural %s study of "'+topic+'" in '+field+'. Generated samples are clearly labeled and never presented as archive records.',
    field:field,
    src:%s,
    sample:true,
    disclaimer:'Generated sample record \\u2014 not an archive record. Seeded archive records are the authoritative entries.',
    demo:{kind:"%s-demo",language:'python',program:demoProgram(topic,field),note:'Structural sample demo.'},
    _seed:seed
  };
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+PREFIX.replace(/-/g,'\\\\-')+'\\\\d{6}$').test(r.id||''))e.push('id');
  if(FIELDS.indexOf(r.field)<0)e.push('field');
  if(!r.src)e.push('src');
  if(!r.demo||!r.demo.program)e.push('demo');
  return {ok:!e.length,errors:e};
}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.field===record.field;});
  return dups.length?{ok:false,errors:['duplicate topic+field in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-%s-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('%s',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
"""

def js_str(s):
    return json.dumps(s)

def build_gen_js(cfg):
    topics = {}
    for f in cfg["fields"]:
        topics[f] = [t["title"] + " \u2014 " + f for t in cfg["topics"] if t["group"] == f]
    src_label = "'signature'" if cfg["src"] == "signature" else "'public-harvest-sample'"
    return GEN_TMPL % (cfg["name"], cfg["slug"], js_str(cfg["prefix"]), js_str(cfg["fields"]),
                       js_str(topics), cfg["name"], cfg["kind"], src_label,
                       cfg["slug"], cfg["slug"], cfg["slug"])

def build_index_html(cfg, template):
    h = template
    sig = cfg["src"] == "signature"
    type_short = "Signature-made original designs" if sig else "Public records organized in the Signature system"
    foot = ("JAH Databases. Signature-made originals. Property of Justin Addam Higgins (JAH), A7 Signature Dominion."
            if sig else "JAH Databases. Public records organized in the Signature system. Property of Justin Addam Higgins (JAH).")
    sigsys = ("Signature-made originals \u2014 every design drawn fresh for the A7 Signature Dominion. Property of Justin Addam Higgins (JAH)."
              if sig else "Public records organized in the Signature system. Property of Justin Addam Higgins (JAH).")
    reps = [
        ("<title>The Life Skills Database \u2014 JAH Databases</title>",
         "<title>%s \u2014 JAH Databases</title>" % cfg["name"]),
        ("Practical life skills guidance \u2014 34 full records with how-it-works, key points, requirements, standards, citations, and working demonstrations. Property of Justin Addam Higgins. Property of Justin Addam Higgins.",
         cfg["desc"]),
        ("Practical life skills guidance \\u2014 34 full records with how-it-works, key points, requirements, standards, citations, and working demonstrations. Property of Justin Addam Higgins.",
         cfg["desc"]),
        ("The All Accidents Insurance-Proven Documentation Database", cfg["name"]),
        ("<h1>The Life Skills Database</h1>", "<h1>%s</h1>" % cfg["name"]),
        ("Practical <b>life skills guidance</b> \u2014 every record carries plain-language steps, checks, and real-world know-how. Every record carries the full entry: practical guidance, how-it-works, key points, requirements, standards, citations, and a working demonstration program.",
         cfg["hero"] + " Every record carries the full entry: description, how-it-works, key points, requirements, standards, citations, and a working demonstration program."),
        ("jahdb-life-skills-1.0", "jahdb-%s-1.0" % cfg["slug"]),
        ("Type: <b>Public records organized in the Signature system</b>", "Type: <b>%s</b>" % type_short),
        ("SLUG='life-skills'", "SLUG='%s'" % cfg["slug"]),
        ("data/life-skills/'", "data/%s/'" % cfg["slug"]),
        ("JAHDB.emblemSVG(db.name,'JAH-LS-')", "JAHDB.emblemSVG(db.name,'%s')" % cfg["prefix"]),
        ("db={slug:SLUG,name:'The Life Skills Database',ai_name:'JAH Life Skills Guide',record_kind:'practical guidance record'}",
         "db={slug:SLUG,name:%s,ai_name:%s,record_kind:%s}" % (js_str(cfg["name"]), js_str(cfg["ai"]), js_str(cfg["kind"]))),
        ("ROLE='life skills guide \u2014 life skills records by tier'", "ROLE=%s" % js_str(cfg["role"])),
        ('placeholder="Search life skills records..."', 'placeholder="Search %ss..."' % cfg["kind"]),
        ("<h3>The The Life Skills Database generator</h3>", "<h3>The %s generator</h3>" % cfg["name"]),
        ("Generate clearly-labeled structural life skills studies.", "Generate clearly-labeled structural %s studies." % cfg["kind"]),
        ("<h3>JAH Life Skills Guide <button", "<h3>%s <button" % cfg["ai"]),
        ('placeholder="Ask about life skills..."', 'placeholder="Ask about %ss..."' % cfg["kind"]),
        ("'I am the JAH Life Skills Guide. Ask me about life skills records.'",
         "'I am the %s. Ask me about %s records.'" % (cfg["ai"], cfg["kind"])),
        ('<script src="gen-life-skills.js"></script>', '<script src="gen-%s.js"></script>' % cfg["slug"]),
        ("Seeded life skills archive (JAH-LS- records), marching toward one million records.",
         "Seeded %s archive (%s records), marching toward one million records." % (cfg["kind"], cfg["prefix"].rstrip("-") + "-")),
        ("<dt>Fields</dt><dd>foundations \u00b7 compounded \u00b7 advanced</dd>",
         "<dt>Fields</dt><dd>%s</dd>" % " \u00b7 ".join(cfg["fields"])),
        ("<dt>AI</dt><dd>JAH Life Skills Guide \u2014 life skills guide \u2014 life skills records by tier \u2014 and aware of the whole JAH Databases network through cross-database reasoning.",
         "<dt>AI</dt><dd>%s \u2014 %s \u2014 and aware of the whole JAH Databases network through cross-database reasoning." % (cfg["ai"], cfg["role"])),
        ("<dt>Signature system</dt><dd>Public records organized in the Signature system. Property of Justin Addam Higgins (JAH).</dd>",
         "<dt>Signature system</dt><dd>%s</dd>" % sigsys),
        ("JAH Databases. Public records organized in the Signature system. Property of Justin Addam Higgins (JAH).", foot),
    ]
    for old, new in reps:
        if old not in h:
            raise SystemExit("REPLACEMENT MISS for %s: %r" % (cfg["slug"], old[:70]))
        h = h.replace(old, new)
    if "life-skills" in h or "Life Skills" in h or "JAH-LS-" in h:
        raise SystemExit("LEFTOVER life-skills token in %s" % cfg["slug"])
    return h

def main():
    with open(os.path.join(REPO, "db", "life-skills", "index.html"), encoding="utf-8") as f:
        template = f.read()
    report = {"built": [], "builder": "supercenter_build.py", "date": "2026-10-19"}
    for cfg in DBS:
        assert len(cfg["topics"]) == 34, (cfg["slug"], len(cfg["topics"]))
        recs = build_records(cfg)
        # data files
        ddir = os.path.join(DATA, cfg["slug"]); cdir = os.path.join(ddir, "chunks")
        os.makedirs(cdir, exist_ok=True)
        with gzip.open(os.path.join(ddir, "index.jsonl.gz"), "wt", encoding="utf-8") as f:
            for r in recs:
                f.write(json.dumps({"id": r["id"], "t": r["t"], "g": r["g"]}, ensure_ascii=False) + "\n")
        with gzip.open(os.path.join(cdir, "chunk-0000.jsonl.gz"), "wt", encoding="utf-8") as f:
            for r in recs:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")
        # page files
        pdir = os.path.join(REPO, "db", cfg["slug"])
        os.makedirs(pdir, exist_ok=True)
        with open(os.path.join(pdir, "gen-%s.js" % cfg["slug"]), "w", encoding="utf-8") as f:
            f.write(build_gen_js(cfg))
        with open(os.path.join(pdir, "index.html"), "w", encoding="utf-8") as f:
            f.write(build_index_html(cfg, template))
        report["built"].append({"slug": cfg["slug"], "name": cfg["name"], "records": len(recs),
                                "id_prefix": cfg["prefix"], "src": cfg["src"], "status": "PASS"})
        print("built", cfg["slug"], len(recs))
    rp = os.path.expanduser("~/workspace/hidden_files/supercenter-build-report.json")
    with open(rp, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=1)
    print("report:", rp)

if __name__ == "__main__":
    main()
